-- 0004_black_road_import.sql
-- The Black Road import slice (BUILD_PLAN.md #2), scoped per the three
-- decisions in SPEC.md's decisions log (2026-08-05, "Black Road import
-- scoping"): fine-grained journal decomposition of Session 1's prose,
-- character sheets + campaign-state.md as the authoritative source over
-- the stale tracker.xlsx, and a full import — characters, quests, npcs,
-- factions, and treasure all land in this one slice, pulling forward
-- schema BUILD_PLAN.md otherwise assigns to slices 3/5/6.
--
-- Five new tables (characters, npcs, factions, quests, treasure), each
-- member-scoped SELECT only, same shape as 0001's campaigns/sessions/
-- journal_entries: no INSERT/UPDATE/DELETE policy on any of them. This
-- migration is itself the only writer today (a one-time historical
-- import, run as the database owner, not through a SECURITY DEFINER
-- command) — future slices add the commands that mutate this data going
-- forward (HP changes, quest status, etc.), same as 0001 did for journal
-- entries.
--
-- Also folds in the vision-handoff decision from the same day's log:
-- 'chat' is added to journal_entries' kind check constraint, since this
-- is the next migration touching that table.

-- ── schema: characters ──────────────────────────────────────────────
-- Stats live in jsonb (abilities, sheet) rather than hardcoded columns —
-- BUILD_PLAN.md's multi-system seam ("JSON-schema character stats").
-- Only the fields PlayerCard/StatTile need to render directly (HP, AC,
-- XP, level, gear slots) are their own queryable columns.
create table characters (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid not null references campaigns(id) on delete cascade,
  member_id uuid references campaign_members(id) on delete set null,
  name text not null,
  class_title text not null,
  background text,
  alignment_title text,
  level int not null default 1,
  xp_current int not null default 0,
  xp_needed int not null default 10,
  hp_current int not null,
  hp_max int not null,
  ac int not null,
  gear_current int,
  gear_max int,
  gold jsonb not null default '{}'::jsonb,
  abilities jsonb not null default '{}'::jsonb,
  sheet jsonb not null default '{}'::jsonb,
  status text not null default 'active',
  created_at timestamptz not null default now()
);

-- ── schema: npcs ─────────────────────────────────────────────────────
-- Hirelings (Rowan, Miri, Hester) are npcs with is_hireling=true and a
-- hire_terms note rather than a separate table — BUILD_PLAN.md's domain
-- component list treats HirelingRow as a display variant, not a
-- distinct data shape, and the NPC log/hireling data share every other
-- field (role, status, stat_block).
create table npcs (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid not null references campaigns(id) on delete cascade,
  name text not null,
  role text,
  location text,
  attitude text,
  status text not null default 'alive',
  is_hireling boolean not null default false,
  hire_terms text,
  stat_block jsonb,
  summary text not null default '',
  created_at timestamptz not null default now()
);

-- ── schema: factions ─────────────────────────────────────────────────
create table factions (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid not null references campaigns(id) on delete cascade,
  name text not null,
  type text,
  leader text,
  territory text,
  goal text,
  disposition text,
  status text,
  notes text,
  created_at timestamptz not null default now()
);

-- ── schema: quests ───────────────────────────────────────────────────
-- status is free text, not a check-constrained enum: the source log uses
-- Active/Accepted/Lead/Personal/etc inconsistently and a filter-chip
-- taxonomy for quests hasn't been specced yet (only journal kind has,
-- per the vision handoff) — constraining it now would be inventing a
-- taxonomy no one asked for.
create table quests (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid not null references campaigns(id) on delete cascade,
  code text not null,
  title text not null,
  status text not null,
  claimant text,
  goal text,
  summary text not null default '',
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  unique (campaign_id, code)
);

-- ── schema: treasure ─────────────────────────────────────────────────
-- quantity_value stays free text ("20 gp 4 sp", "1") rather than a
-- normalized numeric — Shadowdark tracks gp/sp/cp denominations
-- separately and the source data mixes coin totals with singular items;
-- normalizing now would invent a conversion no one asked for.
create table treasure (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid not null references campaigns(id) on delete cascade,
  name text not null,
  category text,
  quantity_value text,
  held_by text,
  location text,
  status text,
  notes text,
  created_at timestamptz not null default now()
);

-- ── RLS ──────────────────────────────────────────────────────────────
alter table characters enable row level security;
alter table npcs enable row level security;
alter table factions enable row level security;
alter table quests enable row level security;
alter table treasure enable row level security;

create policy characters_select_member
  on characters for select
  using (exists (
    select 1 from campaign_members
    where campaign_members.campaign_id = characters.campaign_id
      and campaign_members.user_id = auth.uid()
  ));

create policy npcs_select_member
  on npcs for select
  using (exists (
    select 1 from campaign_members
    where campaign_members.campaign_id = npcs.campaign_id
      and campaign_members.user_id = auth.uid()
  ));

create policy factions_select_member
  on factions for select
  using (exists (
    select 1 from campaign_members
    where campaign_members.campaign_id = factions.campaign_id
      and campaign_members.user_id = auth.uid()
  ));

create policy quests_select_member
  on quests for select
  using (exists (
    select 1 from campaign_members
    where campaign_members.campaign_id = quests.campaign_id
      and campaign_members.user_id = auth.uid()
  ));

create policy treasure_select_member
  on treasure for select
  using (exists (
    select 1 from campaign_members
    where campaign_members.campaign_id = treasure.campaign_id
      and campaign_members.user_id = auth.uid()
  ));

-- ── journal_entries: add 'chat' kind (vision-handoff decision) ────────
alter table journal_entries drop constraint journal_entries_kind_check;
alter table journal_entries add constraint journal_entries_kind_check
  check (kind in ('narration', 'action', 'roll', 'note', 'system', 'chat'));


