('d20f78a5-20c7-4d27-9d47-b3d8c075b128', 'e00ceebd-c2e7-472e-bc6e-feec654ab2a6', '6b54f8ea-e47a-421a-8538-e65962b0d2ae', 'action', 'Kimbo splits the group inside town.', 'Kimbo', timestamptz '2026-08-02 18:00:00+00' + interval '204 minutes'),
